class TestListSuites:
    def test_returns_list(self):
        result = list_suites()
        assert isinstance(result, list)
        assert len(result) > 0

    def test_single_pref_exists(self):
        suites = list_suites()
        assert any("single" in s.lower() or "singpref" in s.lower() or "single-pref" in s.lower()
                    for s in suites), f"No single-pref suite found in {suites}"


class TestLoadSuite:
    def test_returns_list_of_strings(self):
        suites = list_suites()
        missions = load_suite(suites[0])
        assert isinstance(missions, list)
        assert all(isinstance(m, str) for m in missions)

    def test_unknown_suite_raises(self):
        with pytest.raises(KeyError, match="Unknown task_suite"):
            load_suite("nonexistent_suite_xyz")


